INSERT INTO contest_config_templates (id, sport, sport_league_id, event_type, contest_type, selection_type, template_key, name, description, sort_order, is_default, active, config_json, schema_version, event_series_names, created_at, updated_at) VALUES ('aaa6fe91-1c46-4518-a490-3cdf3d5b9063', 'AMERICAN_FOOTBALL', 'f91f2566-1978-4171-a706-ae417c4d601a', 'WEEK', 'PREDICTION', 'PICK_EM', 'nfl-pick-em-against-the-spread', 'Pick’em: every game, against the spread', 'Pick the team that covers the spread in every game. A pick that covers scores a point; a push scores nothing.', 3, false, true, '{"mode": "STRAIGHT_UP", "selectionType": "PICK_EM", "againstTheSpread": true, "maxEntriesPerSquad": 1}', 1, '{}', now(), now());
