INSERT INTO contest_config_templates (id, sport, sport_league_id, event_type, contest_type, selection_type, template_key, name, description, sort_order, is_default, active, config_json, schema_version, event_series_names, created_at, updated_at) VALUES ('2d09e745-6768-4e8c-84df-0e1e176557f6', 'AMERICAN_FOOTBALL', 'f91f2566-1978-4171-a706-ae417c4d601a', 'WEEK', 'PREDICTION', 'SURVIVOR', 'nfl-survivor', 'Survivor: 1 team a week, each team once', 'Pick one team to win each week, never the same team twice. A loss puts the entry out; the last ones standing win.', 4, true, true, '{"selectionType": "SURVIVOR", "maxEntriesPerSquad": 1}', 1, '{}', now(), now());
INSERT INTO contest_config_templates (id, sport, sport_league_id, event_type, contest_type, selection_type, template_key, name, description, sort_order, is_default, active, config_json, schema_version, event_series_names, created_at, updated_at) VALUES ('2838ef18-a556-4594-8326-77545a6bb37e', 'BASKETBALL', '15d608a9-d556-4a65-9cd9-1093f1a40b61', 'KNOCKOUT', 'ROSTER', 'TIERED', 'wnba-tiered-doubling', 'Tiered: 1 team per tier, doubling points', 'Pick one team from each of the four tiers. A series win scores 1 point in the First Round, 2 in the Semifinals and 4 in the WNBA Finals.', 1, true, true, '{"scoring": {"config": {"upsetBonus": {"rule": "NONE"}, "roundValues": [1, 2, 4]}, "participantScoringDefinitionId": "KNOCKOUT_ROUND_POINTS"}, "picksPerTier": 1, "countedScores": 4, "selectionType": "TIERED", "maxEntriesPerSquad": 1}', 1, '{}', now(), now());
INSERT INTO contest_config_templates (id, sport, sport_league_id, event_type, contest_type, selection_type, template_key, name, description, sort_order, is_default, active, config_json, schema_version, event_series_names, created_at, updated_at) VALUES ('bc08b965-76e7-4a19-b883-06377f726b9c', 'AMERICAN_FOOTBALL', 'f91f2566-1978-4171-a706-ae417c4d601a', NULL, 'SQUARES', 'SQUARES', 'nfl-squares', 'Squares: 10 boxes each, every quarter', 'A 10x10 grid on one game: claim up to 10 boxes, then the digits are drawn. The box matching each team''s last digit wins each quarter and the final score.', 10, true, true, '{"selectionType": "SQUARES", "maxEntriesPerSquad": 1, "maxSquaresPerEntry": 10}', 1, '{}', now(), now());
