INSERT INTO contest_config_templates (id, sport, sport_league_id, event_type, contest_type, selection_type, template_key, name, description, sort_order, is_default, active, config_json, schema_version, event_series_names, created_at, updated_at) VALUES ('08d43024-caf1-47f1-b75a-090eafdf0b90', 'SOCCER', 'a91d9af2-757f-4d46-845f-fbd621a2ce6d', 'KNOCKOUT', 'PREDICTION', 'SURVIVOR', 'ncaa-men-soccer-knockout-survivor', 'Survivor: 1 team a round, each team once', 'Pick one team to win in each round, never the same team twice. A loss puts the entry out; the last ones standing win.', 11, true, true, '{"selectionType": "SURVIVOR", "maxEntriesPerSquad": 1}', 1, '{}', now(), now());
INSERT INTO contest_config_templates (id, sport, sport_league_id, event_type, contest_type, selection_type, template_key, name, description, sort_order, is_default, active, config_json, schema_version, event_series_names, created_at, updated_at) VALUES ('b21a682f-68ca-40e2-8cda-dc746aa0e20a', 'SOCCER', 'a91d9af2-757f-4d46-845f-fbd621a2ce6d', 'KNOCKOUT', 'SQUARES', 'SQUARES', 'ncaa-men-soccer-squares', 'Squares: 10 boxes each, every half', 'A 10x10 grid on one match: claim up to 10 boxes, then the digits are drawn. The box matching each team''s last digit wins at half time and on the final score.', 10, true, true, '{"selectionType": "SQUARES", "maxEntriesPerSquad": 1, "maxSquaresPerEntry": 10}', 1, '{}', now(), now());
